import org.jsoup.helper.HttpConnection;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

public class HttpConnectionTest {

    private HttpConnection connection;
    private URL url;

    @Before
    public void setup() {
        url = new URL("https://example.com");
    }

    @Test
    public void testConnect_WithoutParams() throws Exception {
        connection = HttpConnection.connect(url);
        assertTrue(connection instanceof Connection);
    }

    @Test
    public void testConnect_WithHttpOnlyParams() throws Exception {
        String params = "param1=value1&param2=value2";
        connection = HttpConnection.connect(url, params);
        assertTrue(params.startsWith("HTTPONLY"));
    }

    @Test
    public void testConnect_WithQueryString() throws Exception {
        String urlStr = "https://example.com?param1=value1&param2=value2";
        connection = HttpConnection.connect(new URL(urlStr));
        assertTrue(connection instanceof Connection);
    }

    @Test
    public void testConnect_WithPathParams() throws Exception {
        String urlStr = "/path/to/resource?param1=value1&param2=value2";
        connection = HttpConnection.connect(new URL(urlStr));
        assertTrue(connection instanceof Connection);
    }

    @Test
    public void testConnect_WithQueryParams() throws Exception {
        String urlStr = "https://example.com?param1=value1&param2=value2#fragment";
        connection = HttpConnection.connect(new URL(urlStr));
        assertTrue(connection instanceof Connection);
    }

    @Test
    public void testConnect_WithoutCookies() throws Exception {
        String cookieStore = null;
        connection = HttpConnection.connect(url, cookieStore);
        assertTrue(connection instanceof Connection);
    }

    @Test
    public void testConnect_WithCookies() throws Exception {
        CookieManager cookieManager = new CookieManager();
        connection = HttpConnection.connect(url, cookieManager);
        assertTrue(connection instanceof Connection);
    }

    @Test
    public void testGet() throws Exception {
        String responseText = "Hello World!";
        connection = (HttpConnection) new Request().setEntity(new StringReader(responseText));
        assertEquals("Hello World!", new BufferedReader(new InputStreamReader(connection.get()))!!.readLine());
    }

    @Test
    public void testPost() throws Exception {
        String responseText = "Hello World!";
        Request request = new Request();
        connection = (HttpConnection) request.get().setEntity(new StringReader(responseText));
        assertEquals("Hello World!", new BufferedReader(new InputStreamReader(connection.post().get()))!!.readLine());
    }

    @Test
    public void testResponse() throws Exception {
        String responseText = "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\nHello World!";
        Request request = new Request();
        connection = (HttpConnection) request.get().setEntity(new StringReader(responseText));
        assertEquals("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\nHello World!", new BufferedReader(new InputStreamReader(connection.response().get()))!!.readLine());
    }
